DO $$ BEGIN
    IF EXISTS (
        SELECT 1 FROM _arloraka_seed_products s JOIN arloraka.products p USING (product_id)
        WHERE p.product_code <> s.product_code
    ) THEN RAISE EXCEPTION 'ID produk sudah dipakai untuk kode produk berbeda. Periksa pemetaan.'; END IF;
    IF EXISTS (
        SELECT 1 FROM _arloraka_seed_sales_reports s JOIN arloraka.sales_reports r USING (report_id)
        WHERE r.source_dataset IS DISTINCT FROM s.source_dataset
           OR r.source_transaction_id IS DISTINCT FROM s.source_transaction_id
    ) THEN RAISE EXCEPTION 'ID laporan sudah dipakai sumber berbeda. Import dibatalkan.'; END IF;
END; $$;


INSERT INTO arloraka.freelancers (freelancer_id, display_name, is_active, is_dummy) SELECT freelancer_id, display_name, is_active, is_dummy FROM _arloraka_seed_freelancers
ON CONFLICT (freelancer_id) DO NOTHING;

INSERT INTO arloraka.products (product_id, product_code, product_name, current_price, is_active) SELECT product_id, product_code, product_name, current_price, is_active FROM _arloraka_seed_products
ON CONFLICT (product_id) DO NOTHING;


CREATE TEMP TABLE _arloraka_seed_inserted_reports (report_id TEXT PRIMARY KEY) ON COMMIT DROP;
WITH inserted AS (
    INSERT INTO arloraka.sales_reports (report_id, source_dataset, source_transaction_id, freelancer_id, sale_date, status, total_bottles, gross_amount, payment_method, sale_location, notes, is_dummy)
    SELECT report_id, source_dataset, source_transaction_id, freelancer_id, sale_date, status, total_bottles, gross_amount, payment_method, sale_location, notes, is_dummy FROM _arloraka_seed_sales_reports
    ON CONFLICT (source_dataset, source_transaction_id) DO NOTHING
    RETURNING report_id
)
INSERT INTO _arloraka_seed_inserted_reports SELECT report_id FROM inserted;

-- Rincian hanya diisi untuk header yang benar-benar baru pada import ini.
INSERT INTO arloraka.sales_report_items (report_id, product_id, product_name_at_sale, quantity, unit_price_at_sale)
SELECT s.report_id, s.product_id, s.product_name_at_sale, s.quantity, s.unit_price_at_sale
FROM _arloraka_seed_sales_report_items s
JOIN _arloraka_seed_inserted_reports n ON n.report_id = s.report_id;

SET CONSTRAINTS ALL IMMEDIATE;
SELECT COUNT(*) AS newly_inserted_reports FROM _arloraka_seed_inserted_reports;
COMMIT;

